// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != c.owner());
        vm.assume(amount <= address(this).balance);
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        bool revertOccurred = true;
        try c.sendMoney(nonOwner, amount, "") {
            revertOccurred = false;
        } catch {
            revertOccurred = true;
        }
        assertTrue(revertOccurred);
    }
}
